TYPE.TEST:


SetFunctionName("Soa4Vector2()");

Soa4Vector2 v;

Validate( true ); // Take address of v so that it is referenced


SetFunctionName("Soa4Vector2(const Soa4Vector2&)");

Soa4Vector2 ref( mA );

Validate( IsEqual( ref, mA ) );


SetFunctionName("Soa4Vector2(Soa4Float)");

Soa4Vector2 ref( Soa4FloatFromFloat( 1.0f ) );

Validate( IsEqual( ref, mOne ) );



SetFunctionName("Soa4Vector2(VectorIntrinsic)");

VectorIntrinsic vx, vy;
vx = Soa4FloatFromFloat( 1.0f ).mV;
vy = Soa4FloatFromFloat( 1.0f ).mV;

Soa4Vector2 ref( vx, vy );

Validate( IsEqual( ref, mOne ) );


SetFunctionName("Soa4Vector2 operator=(const Soa4Vector2&)");

Soa4Vector2 ref( mZero );
Validate( !IsEqual( ref, mOne ) );

ref = mOne;

Validate( IsEqual( ref, mOne ) );
Validate( &ref.x != &mOne.x && &ref.y != &mOne.y );


SetFunctionName("X()");

Soa4Vector2 ref( mNegOne );

const Soa4Float& cx = ref.X();
Validate( IsEqual( cx, ref.x ) );

Soa4Float& x = ref.X();

x = Soa4FloatFromFloat( 1.0f );

Validate( !IsEqual( ref, mOne ) );
Validate( IsEqual( ref.x, Soa4FloatFromFloat(  1.0f ) ) );
Validate( IsEqual( ref.y, Soa4FloatFromFloat( -1.0f ) ) );


SetFunctionName("X()");

Soa4Vector2 ref( mNegOne );

const Soa4Float& cy = ref.Y();
Validate( IsEqual( cy, ref.y ) );

Soa4Float& y = ref.Y();

y = Soa4FloatFromFloat( 1.0f );

Validate( !IsEqual( ref, mOne ) );
Validate( IsEqual( ref.x, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.y, Soa4FloatFromFloat(  1.0f ) ) );


SetFunctionName("Soa4Vector2FromVector2(Vector2::InParam v)");

Vector2 v( 1.0f, -1.0f );
Soa4Vector2 sv = Soa4Vector2FromVector2( v );
Validate( IsEqual( sv.x, Soa4FloatFromFloat(  1.0f ) ) );
Validate( IsEqual( sv.y, Soa4FloatFromFloat( -1.0f ) ) );


SetFunctionName("Soa4Vector2FromVector2(Vector2::InParam v0, Vector2::InParam v1, Vector2::InParam v2, Vector2::InParam v3)");

// These are the same values as in the member vector "mA"
Vector2 v0( -1.0f, 5.0f );
Vector2 v1(  2.0f, 3.0f );
Vector2 v2(  3.0f, 3.0f );
Vector2 v3( -4.0f, 1.0f );

Soa4Vector2 sv = Soa4Vector2FromVector2( v0, v1, v2, v3 );

Validate( IsEqual( sv, mA ) );


SetFunctionName("Soa4Vector2FromVector2(const Vector2*)");

// These are the same values as in the member vector "mA"
Vector2 v[4] = {
    Vector2( -1.0f, 5.0f ),
    Vector2(  2.0f, 3.0f ),
    Vector2(  3.0f, 3.0f ),
    Vector2( -4.0f, 1.0f )
};

Soa4Vector2 sv = Soa4Vector2FromVector2( v );

Validate( IsEqual( sv, mA ) );


SetFunctionName("Vector2FromSoa4Vector2(Soa4Vector2::InParam, Vector2& v0, Vector2& v1, Vector2& v2, Vector2& v3)");
Vector2 v0, v1, v2, v3;
Vector2 rv0( -1.0f, 5.0f );
Vector2 rv1(  2.0f, 3.0f );
Vector2 rv2(  3.0f, 3.0f );
Vector2 rv3( -4.0f, 1.0f );

Vector2FromSoa4Vector2( mA, v0, v1, v2, v3 );
Validate( IsEqual( v0, rv0 ) );
Validate( IsEqual( v1, rv1 ) );
Validate( IsEqual( v2, rv2 ) );
Validate( IsEqual( v3, rv3 ) );


SetFunctionName("Vector2FromSoa4Vector2(Soa4Vector2::InParam, Vector2* v)");
Vector2 v[4];
Vector2 rv0( -1.0f, 5.0f );
Vector2 rv1(  2.0f, 3.0f );
Vector2 rv2(  3.0f, 3.0f );
Vector2 rv3( -4.0f, 1.0f );

Vector2FromSoa4Vector2( mA, v );
Validate( IsEqual( v[0], rv0 ) );
Validate( IsEqual( v[1], rv1 ) );
Validate( IsEqual( v[2], rv2 ) );
Validate( IsEqual( v[3], rv3 ) );


SetFunctionName("operator *= (Soa4Vector2& v, Soa4Float::InParam a)");

