Soa4Vector2 ref;
ref.x.mV = Set( -2.0f, 4.0f, 6.0f, -8.0f );
ref.y.mV = Set( 10.0f, 6.0f, 6.0f, 2.0f );
Validate( IsEqual( ref, s ) );

