SetFunctionName("Magnitude(Soa4Vector2::InParam v)");

Soa4Float ref = Soa4FloatFromFloats( 5.0990195135927848300282241090228f,
                    3.6055512754639892931192212674705f,
                    4.2426406871192851464050661726291f,
                    4.1231056256176605498214098559741f );

Soa4Float invRef = Soa4FloatFromFloats( 0.19611613513818403192416246573168f,
                    0.27735009811261456100917086672854f,
                    0.23570226039551584146694812070162f,
                    0.24253562503633297351890646211612f );

{
