//-----------------------------------------------------------------------



Soa4Vector2 ref( mA );

Soa4Float mag = Soa4FloatFromFloats( 5.0990195135927848300282241090228f,
                    3.6055512754639892931192212674705f,
                    4.2426406871192851464050661726291f,
                    4.1231056256176605498214098559741f );


Soa4Float invMag = Soa4FloatFromFloats( 0.19611613513818403192416246573168f,
                    0.27735009811261456100917086672854f,
                    0.23570226039551584146694812070162f,
                    0.24253562503633297351890646211612f );

ref *= invMag;

Soa4Float one = Soa4FloatFromFloats( 1.0f, 1.0f, 1.0f, 1.0f );


SetFunctionName("NormalizeFast(Soa4Vector2::InParam v)");

{
    Soa4Vector2 res = NormalizeFast( mA );
    Validate( IsEqualWithEpsilon( res, ref ) );
    Validate( IsEqualWithEpsilon( Magnitude( res ), one ) );
    Validate( IsEqualWithEpsilon( mA, Mult( res, mag ) ) );
}

//-----------------------------------------------------------------------

SetFunctionName("NormalizeEstimate(Soa4Vector2::InParam v)");

{
    Soa4Vector2 res = NormalizeEstimate( mA );
    Validate( IsEqualWithEpsilon( res, ref, Soa4FloatFromFloat(0.003f) ) );
    Validate( IsEqualWithEpsilon( Magnitude( res ), one, Soa4FloatFromFloat(0.003f) ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Normalize(Soa4Vector2::InParam v)");

{
    Soa4Vector2 res = Normalize( mA );
    Validate( IsEqualWithEpsilon( res, ref ) );
    Validate( IsEqualWithEpsilon( Magnitude( res ), one ) );
    Validate( IsEqualWithEpsilon( mA, Mult( res, mag ) ) );
}

//-----------------------------------------------------------------------

SetFunctionName("NormalizeReturnMagnitude(Soa4Vector2::InParam v, Soa4Vector2& result)");

{
    Soa4Vector2 res;
    Soa4Float testMagnitude = NormalizeReturnMagnitude( mA, res );
    Validate( IsEqualWithEpsilon( res, ref ) );
    Validate( IsEqualWithEpsilon( testMagnitude, mag ) );
    Validate( IsEqualWithEpsilon( Magnitude( res ), one ) );                
    Validate( IsEqualWithEpsilon( mA, Mult( res, mag ) ) );
}

//-----------------------------------------------------------------------

SetFunctionName("CheckedNormalizeReturnMagnitude(Soa4Vector2::InParam v, Soa4Float& magnitude)");

{
    VectorIntrinsic ax = CreateSoa4Float(-1.0f, 0.0f, 3.0f, -4.0f).mV;
    VectorIntrinsic ay = CreateSoa4Float(5.0f, 0.0f, 3.0f,  1.0f).mV;
    Soa4Vector2 vec( ax, ay );

    Soa4Float zeroComponentMagnitude =  Soa4FloatFromFloats( 5.0990195135927848300282241090228f,
                    0.0f,
                    4.2426406871192851464050661726291f,
                    4.1231056256176605498214098559741f );

    Soa4Vector2 res;
    Soa4Float testMagnitude = CheckedNormalizeReturnMagnitude( vec, res );
    Soa4Vector2 nonChecked = Normalize( vec );

    Validate( !IsEqual( nonChecked, vec ) );
    Validate( IsEqualWithEpsilon( zeroComponentMagnitude, testMagnitude ) );
    Validate( IsEqualWithEpsilon( vec, Mult( res, testMagnitude ) ) );
}



Soa4Float t = Soa4FloatFromFloats( 0.25f, 0.5f, 0.75f, 1.0f );
Soa4Vector2 ref = Soa4Vector2(
    Soa4FloatFromFloats( 7.75f, 4.5f, -2.75f, 2.0f ),
    Soa4FloatFromFloats( 3.75f, 2.0f,  0.25f, 2.0f ) );
Soa4Vector2 normalRef = Normalize( ref );

SetFunctionName("Lerp(Soa4Vector2::InParam v0, Soa4Vector2::InParam v1, Soa4Float::InParam t)");

{
    Soa4Vector2 res = Lerp( mB, mC, t );
    Validate( IsEqual( res, ref ) );
}

//-----------------------------------------------------------------------


SetFunctionName("SLerp(Soa4Vector2::InParam v0, Soa4Vector2::InParam v1, Soa4Float::InParam t)");

{
    Soa4Vector2 a( Soa4FloatFromFloat( 1.0f ), Soa4FloatFromFloat( 2.0f ) );
    Soa4Vector2 b( Soa4FloatFromFloat( -3.0f ), Soa4FloatFromFloat( 1.0f ) );
    Soa4Float slerpT( Soa4FloatFromFloats( 0.75f, 0.75f, 0.75f, 0.75f ) );
    Soa4Vector2 normalA = Normalize( a );
    Soa4Vector2 normalB = Normalize( b );

    Soa4Vector2 output = SLerp( normalA, normalB, slerpT );

    Soa4Vector2 slerpRef( Soa4FloatFromFloat( -0.73185913885907916f ), Soa4FloatFromFloat( 0.68134627789812985f ) );
    Validate( IsEqualWithEpsilon( output, slerpRef ) );
}

//-----------------------------------------------------------------------

SetFunctionName("NLerpEstimate(Soa4Vector2::InParam v0, Soa4Vector2::InParam v1, Soa4Float::InParam t)");

{
    Soa4Vector2 res = NLerpEstimate( mB, mC, t );
    Validate( IsEqualWithEpsilon( res, normalRef, Soa4FloatFromFloat(0.003f) ) );
}

