SetFunctionName("ClampToNegPosRange(Soa4Vector2::InParam vecToClamp, Soa4Vector2::InParam range)");

{
    VectorIntrinsic r[2] = {
        CreateSoa4Float( 1.0f, 1.0f, 1.0f, 1.0f ).mV,
        CreateSoa4Float( 2.0f, 2.0f, 2.0f, 2.0f ).mV
    };
    Soa4Vector2 range( r[0], r[1] );
    Soa4Vector2 res = ClampToNegPosRange( mA, range );
    VectorIntrinsic v[2] = {
        CreateSoa4Float( -1.0f, 1.0f, 1.0f, -1.0f ).mV,
        CreateSoa4Float( 2.0f, 2.0f, 2.0f, 1.0f ).mV
    };
    Soa4Vector2 ref( v[0], v[1] );

    Validate( IsEqual( res, ref ) );
}


