SetFunctionName("AngleBetweenVectors(Soa4Vector2::InParam v0, Soa4Vector2::InParam v1)");

{
    Soa4Vector2 normalizedA = Normalize( mA );
    Soa4Vector2 normalizedB = Normalize( mB );
    Soa4Float refAngle = Dot( normalizedA, normalizedB );
    Soa4Float ref;
    RW_MATH_VPU_ACos( ref.mV, refAngle.mV );

    Soa4Float res = AngleBetweenVectors( mA, mB );
    Validate( IsEqualWithEpsilon( ref, res ) );
}

