SetFunctionName("CosAngleBetweenNormalizedVectors(Soa4Vector2::InParam v0, Soa4Vector2::InParam v1)");

{
    Soa4Vector2 normalizedA = Normalize( mA );
    Soa4Vector2 normalizedB = Normalize( mB );
    Soa4Float refAngle = Dot( normalizedA, normalizedB );
    Soa4Float res = CosAngleBetweenNormalizedVectors( normalizedA, normalizedB );

    Validate( IsEqual( refAngle, res ) );
}



